event.text:
{
  "file": "package.json",
  "expr": "$ | {scripts, devDependencies}",
  "matched": 1,
  "returned": 1,
  "rows": [
    {
      "path": "$",
      "value": {
        "scripts": {
          "build": "node esbuild.mjs",
          "watch": "node esbuild.mjs --watch",
          "typecheck": "tsc --noEmit -p tsconfig.json",
          "test": "vitest run",
          "prompts": "esbuild scripts/prompts.ts --bundle --platform=node --format=cjs --target=node22 --external:vscode --loader:.md=text --log-level=warning --outfile=dist/prompts.cjs && node dist/prompts.cjs",
          "package": "npm run typecheck && node esbuild.mjs --target=win32-x64 && node scripts/marketplace-readme.mjs && vsce package --no-dependencies --readme-path dist/marketplace-readme.md --target win32-x64 && node esbuild.mjs --target=win32-arm64 && node scripts/marketplace-readme.mjs && vsce package --no-dependencies --readme-path dist/marketplace-readme.md --target win32-arm64",
          "link-dev": "node scripts/link-dev.mjs",
          "unlink-dev": "node scripts/link-dev.mjs --unlink",
          "publish": "npm run typecheck && node esbuild.mjs --target=win32-x64 && node scripts/marketplace-readme.mjs && vsce publish --no-dependencies --readme-path dist/marketplace-readme.md --target win32-x64 && node esbuild.mjs --target=win32-arm64 && node scripts/marketplace-readme.mjs && vsce publish --no-dependencies --readme-path dist/marketplace-readme.md --target win32-arm64"
        },
        "devDependencies": {
          "@types/node": "^22.0.0",
          "@types/vscode": "~1.100.0",
          "@vscode/vsce": "^3.9.2",
          "esbuild": "^0.28.2",
          "jsdom": "^30.0.1",
          "typescript": "^5.9.0",
          "vitest": "^5.0.3"
        }
      }
    }
  ],
  "truncated": null
}

input.old_string:
include: ['test/**/*.test.ts'],
// Each file gets its own isolated worker (the default). Sharing a worker
// between files was tried here to avoid a spawn storm, but on vitest 5.0.3
// it makes every file fail before its first test ("Cannot read properties
// of undefined (reading 'config')", "Vitest failed to find the runner"),
// and it leaked jsdom/module state between unrelated files besides.

input.new_string:
include: ['test/**/*.test.ts'],
// Worker threads, not child processes: one isolated worker per file (the
// default isolation) over 120+ files means 120+ spawns, and spawning that
// many processes on this machine intermittently starves them mid-startup,
// failing whole files before their first test ("Cannot read properties of
// undefined (reading 'config')", "Vitest failed to find the runner") with
// no code at fault. Threads are cheap enough to survive it and keep the
// per-file isolation; sharing one worker between files was tried instead
// and leaked jsdom/module state between unrelated files.
pool: 'threads',
